INSERT INTO `DocumentVersions` VALUES
(1,1,1,0,'Criação inicial','<h2>Antes de começar</h2><ul><li>Confirme os acessos, materiais e condições necessários para executar o procedimento.</li><li>Verifique se o sistema e o ambiente correspondem ao escopo deste documento.</li><li>Avise as pessoas envolvidas quando a atividade puder afetar o serviço.</li></ul><h2>1. Iniciar o procedimento</h2><p>Descreva o objetivo deste documento.</p><figure><p>Insira uma captura de tela ou ilustração desta etapa usando o botão Imagem.</p><figcaption>Figura 1. Descreva o que a imagem mostra.</figcaption></figure><h2>2. Executar a atividade</h2><ol><li>Registre cada ação na ordem em que deve ser realizada.</li><li>Indique os campos, opções e valores que precisam ser selecionados.</li><li>Inclua uma imagem quando ela ajudar a localizar um controle ou confirmar uma etapa.</li></ol><h2>3. Validar o resultado</h2><p>Descreva como confirmar que a atividade foi concluída corretamente e o que fazer se o resultado esperado não ocorrer.</p><h2>Conferência final</h2><ul><li>O procedimento foi concluído no sistema e ambiente corretos.</li><li>O resultado foi validado e as evidências necessárias foram registradas.</li><li>As pessoas envolvidas foram informadas sobre a conclusão.</li></ul>',NULL,NULL,NULL,NULL,NULL,1,'2026-10-22 11:39:47.064',0),
(2,2,1,0,'Criação inicial','<h2>Antes de começar</h2><ul><li>Confirme os acessos, materiais e condições necessários para executar o procedimento.</li><li>Verifique se o sistema e o ambiente correspondem ao escopo deste documento.</li><li>Avise as pessoas envolvidas quando a atividade puder afetar o serviço.</li></ul><h2>1. Iniciar o procedimento</h2><p>Descreva o objetivo deste documento.</p><figure><p>Insira uma captura de tela ou ilustração desta etapa usando o botão Imagem.</p><figcaption>Figura 1. Descreva o que a imagem mostra.</figcaption></figure><h2>2. Executar a atividade</h2><ol><li>Registre cada ação na ordem em que deve ser realizada.</li><li>Indique os campos, opções e valores que precisam ser selecionados.</li><li>Inclua uma imagem quando ela ajudar a localizar um controle ou confirmar uma etapa.</li></ol><h2>3. Validar o resultado</h2><p>Descreva como confirmar que a atividade foi concluída corretamente e o que fazer se o resultado esperado não ocorrer.</p><h2>Conferência final</h2><ul><li>O procedimento foi concluído no sistema e ambiente corretos.</li><li>O resultado foi validado e as evidências necessárias foram registradas.</li><li>As pessoas envolvidas foram informadas sobre a conclusão.</li></ul>',NULL,NULL,NULL,NULL,NULL,1,'2026-10-22 11:40:34.442',0),
(3,3,1,0,'Criação inicial','<h2><br></h2>','c138e76ef7f44d9f8af6e6dda3840eac.docx','�L<_�Y��괱��~�⛧�[�h\0��gݔa�','IBM-POP01 - Cadastro de Dispositivo no IBM MaaS360.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',842885,1,'2026-10-22 19:45:33.496',0),
(4,4,1,0,'Criação inicial','<h2>\r\n\r\n<p><span>Cadastro de dispositivo no IBM MaaS360</span></p>\r\n\r\n\r\n\r\n<p><span style=\"font-size:11pt\">Objetivo: orientar o preparo do\r\ncelular Android, o cadastro no console MaaS360, a aplicação da política e a\r\ndistribuição dos aplicativos necessários.</span><span></span></p>\r\n\r\n<table>\r\n <tbody><tr>\r\n  <td>\r\n  <p><b><span style=\"font-size:8pt\">TIPO&nbsp; •&nbsp;\r\n  Procedimento</span></b><span></span></p>\r\n  </td>\r\n  <td>\r\n  <p><b><span style=\"font-size:8pt\">ESCOPO&nbsp; •&nbsp;\r\n  Android / AFW</span></b><span></span></p>\r\n  </td>\r\n  <td>\r\n  <p><b><span style=\"font-size:8pt\">SISTEMA&nbsp; •&nbsp;\r\n  IBM MaaS360</span></b><span></span></p>\r\n  </td>\r\n </tr>\r\n</tbody></table>\r\n\r\n</h2><span>Antes de começar</span><h2>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>Confirme que o celular foi\r\nformatado e está na tela de configuração inicial, na etapa de configuração de\r\ne-mail/conta.</span></p>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>Tenha acesso ao console IBM\r\nMaaS360 e saiba qual usuário, plataforma e policy devem ser associados ao\r\naparelho.</span></p>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>Mantenha o aparelho conectado à\r\ninternet durante o provisionamento.</span></p>\r\n\r\n</h2><span>1. Iniciar a configuração do celular</span><h2>\r\n\r\n<p><span>Na tela de configuração do Android, digite\r\nAFW#MAAS360 no campo de e-mail ou conta corporativa para iniciar o\r\nprovisionamento pelo Android Enterprise. Siga as instruções apresentadas no\r\npróprio aparelho até concluir a configuração inicial.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shapetype id=\"_x0000_t75\"\r\n coordsize=\"21600,21600\" o:spt=\"75\" o:preferrelative=\"t\" path=\"m@4@5l@4@11@9@11@9@5xe\"\r\n filled=\"f\" stroked=\"f\">\r\n <v:stroke joinstyle=\"miter\"/>\r\n <v:formulas>\r\n  <v:f eqn=\"if lineDrawn pixelLineWidth 0\"/>\r\n  <v:f eqn=\"sum @0 1 0\"/>\r\n  <v:f eqn=\"sum 0 0 @1\"/>\r\n  <v:f eqn=\"prod @2 1 2\"/>\r\n  <v:f eqn=\"prod @3 21600 pixelWidth\"/>\r\n  <v:f eqn=\"prod @3 21600 pixelHeight\"/>\r\n  <v:f eqn=\"sum @0 0 1\"/>\r\n  <v:f eqn=\"prod @6 1 2\"/>\r\n  <v:f eqn=\"prod @7 21600 pixelWidth\"/>\r\n  <v:f eqn=\"sum @8 21600 0\"/>\r\n  <v:f eqn=\"prod @7 21600 pixelHeight\"/>\r\n  <v:f eqn=\"sum @10 21600 0\"/>\r\n </v:formulas>\r\n <v:path o:extrusionok=\"f\" gradientshapeok=\"t\" o:connecttype=\"rect\"/>\r\n <o:lock v:ext=\"edit\" aspectratio=\"t\"/>\r\n</v:shapetype><v:shape id=\"Picture_x0020_1\" o:spid=\"_x0000_i1030\" type=\"#_x0000_t75\"\r\n style=\'width:478.5pt;height:280.5pt;visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/png;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Ilustração do ponto de entrada do código AFW.\r\nAs telas podem variar conforme o fabricante e a versão do Android.</span></i><span></span></p>\r\n\r\n</h2><span>&nbsp;</span><span>2. Abrir o inventário de dispositivos</span><h2>\r\n\r\n\r\n\r\n<p><span>No console MaaS360, use a navegação\r\nsuperior e clique em Devices. A página Device Inventory será exibida.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shape id=\"Picture_x0020_2\"\r\n o:spid=\"_x0000_i1029\" type=\"#_x0000_t75\" style=\'width:479.25pt;height:243.75pt;\r\n visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image003.jpg\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/jpeg;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Figura 1. Acesso a Devices pela navegação\r\nprincipal.</span></i><span></span></p>\r\n\r\n</h2><span>3. Iniciar a inclusão do aparelho</span><h2>\r\n\r\n<p><span>Na página Device Inventory, clique em Add\r\nDevice, no canto superior direito, para abrir o formulário de cadastro.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shape id=\"Picture_x0020_3\"\r\n o:spid=\"_x0000_i1028\" type=\"#_x0000_t75\" style=\'width:479.25pt;height:243pt;\r\n visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image005.jpg\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/jpeg;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Figura 2. Botão Add Device no inventário.</span></i><span></span></p>\r\n\r\n</h2><span>4. Informar o usuário e definir a plataforma e a policy</span><h2>\r\n\r\n<p><span>Na aba Basic, localize o campo Username.\r\nSelecione um usuário existente na lista. Se o usuário ainda não existir, clique\r\nem Add e cadastre-o; depois de salvo, ele será incluído na lista para uso\r\nfuturo.</span></p>\r\n\r\n<p><span>Para um novo cadastro, informe o domínio\r\nGACC e o endereço de e-mail definido para o caso. Para usuários já cadastrados,\r\nos dados correspondentes são preenchidos pelo sistema. Confira os dados antes\r\nde avançar.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shape id=\"Picture_x0020_4\"\r\n o:spid=\"_x0000_i1027\" type=\"#_x0000_t75\" style=\'width:479.25pt;height:243.75pt;\r\n visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image007.jpg\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/jpeg;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Figura 3. Aba Basic do formulário Add Device,\r\ncom os campos de usuário, domínio e e-mail.</span></i><span></span></p>\r\n\r\n<p><span>Abra a aba Advanced. Em Platform &amp; MDM\r\nPolicy, selecione a plataforma correspondente ao aparelho e a policy definida\r\npara o uso. Revise as seleções e clique em Send Request para enviar o cadastro.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shape id=\"Picture_x0020_5\"\r\n o:spid=\"_x0000_i1026\" type=\"#_x0000_t75\" style=\'width:479.25pt;height:243.75pt;\r\n visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image009.jpg\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/jpeg;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Figura 4. Aba Advanced, onde são selecionadas a\r\nplataforma e a policy.</span></i><span></span></p>\r\n\r\n</h2><span>5. Distribuir os aplicativos</span><h2>\r\n\r\n<p><span>Após o envio do cadastro, confirme que o\r\ndispositivo aparece no inventário com a policy atribuída e o status de\r\ngerenciamento esperado. Na linha do dispositivo, clique em More e selecione\r\nDistribute App.</span></p>\r\n\r\n<p><span><!--[if gte vml 1]><v:shape id=\"Picture_x0020_6\"\r\n o:spid=\"_x0000_i1025\" type=\"#_x0000_t75\" style=\'width:479.25pt;height:243.75pt;\r\n visibility:visible;mso-wrap-style:square\'>\r\n <v:imagedata src=\"file:///C:/Users/ICARO~1.SAN/AppData/Local/Temp/msohtmlclip1/01/clip_image011.jpg\"\r\n  o:title=\"\"/>\r\n</v:shape><![endif]--><!--[if !vml]--><img src=\"data:image/jpeg;base64,\"><!--[endif]--></span><span></span></p>\r\n\r\n<p><i><span style=\"font-size:8pt;color:rgb(90, 105, 125)\">Figura 5. A opção Distribute App no menu More\r\ndo dispositivo.</span></i><span></span></p>\r\n\r\n<p><span>Na janela de distribuição, selecione os\r\naplicativos que deverão ficar disponíveis para instalação no aparelho e\r\nconfirme a ação. O usuário poderá instalar os aplicativos disponibilizados\r\nconforme as regras da policy.</span></p>\r\n\r\n</h2><span>Conferência final</span><h2>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>O aparelho concluiu a\r\nconfiguração inicial e aparece no Device Inventory.</span></p>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>O usuário e os dados de\r\ndomínio/e-mail estão corretos.</span></p>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>A plataforma e a policy\r\ncorrespondem ao aparelho e ao uso previsto.</span></p>\r\n\r\n<p><!--[if !supportLists]--><span>·<span style=\"font-size:7pt\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span><!--[endif]--><span>Os aplicativos necessários\r\nforam selecionados em Distribute App.</span></p></h2><ul><li>O resultado foi validado e as evidências necessárias foram registradas.</li><li>As pessoas envolvidas foram informadas sobre a conclusão.</li></ul>','034c73b7e93644c98351cb4d7e814653.docx','�L<_�Y��괱��~�⛧�[�h\0��gݔa�','IBM-POP01 - Cadastro de Dispositivo no IBM MaaS360.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',842885,1,'2026-10-22 19:55:36.316',0),
(5,5,1,0,'Criação inicial','<h2>Antes de começar</h2><ul><li>Confirme os acessos, materiais e condições necessários para executar o procedimento.</li><li>Verifique se o sistema e o ambiente correspondem ao escopo deste documento.</li><li>Avise as pessoas envolvidas quando a atividade puder afetar o serviço.</li></ul><h2>1. Iniciar o procedimento</h2><p>Descreva o objetivo deste documento.</p><figure><p>Insira uma captura de tela ou ilustração desta etapa usando o botão Imagem.</p><figcaption>Figura 1. Descreva o que a imagem mostra.</figcaption></figure><h2>2. Executar a atividade</h2><ol><li>Registre cada ação na ordem em que deve ser realizada.</li><li>Indique os campos, opções e valores que precisam ser selecionados.</li><li>Inclua uma imagem quando ela ajudar a localizar um controle ou confirmar uma etapa.</li></ol><h2>3. Validar o resultado</h2><p>Descreva como confirmar que a atividade foi concluída corretamente e o que fazer se o resultado esperado não ocorrer.</p><h2>Conferência final</h2><ul><li>O procedimento foi concluído no sistema e ambiente corretos.</li><li>O resultado foi validado e as evidências necessárias foram registradas.</li><li>As pessoas envolvidas foram informadas sobre a conclusão.</li></ul>',NULL,NULL,NULL,NULL,NULL,1,'2026-10-23 12:02:39.596',0),
