--
-- Table structure for table `Documents`
--

DROP TABLE IF EXISTS `Documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `Documents` (
  `DocumentId` bigint(20) NOT NULL AUTO_INCREMENT,
  `DocumentCode` varchar(13) DEFAULT NULL,
  `Title` varchar(240) NOT NULL,
  `Summary` varchar(1000) DEFAULT NULL,
  `DocumentType` varchar(30) NOT NULL,
  `CategoryId` int(11) NOT NULL,
  `SystemId` int(11) DEFAULT NULL,
  `LifecycleState` varchar(20) NOT NULL DEFAULT 'Revisao',
  `CurrentVersionId` bigint(20) DEFAULT NULL,
  `OwnerUserId` bigint(20) NOT NULL,
  `CreatedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `UpdatedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `DeletedAt` datetime(3) DEFAULT NULL,
  `IsHidden` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`DocumentId`),
  UNIQUE KEY `DocumentCode` (`DocumentCode`),
  KEY `FK_Documents_Category` (`CategoryId`),
  KEY `FK_Documents_Owner` (`OwnerUserId`),
  KEY `IX_Documents_State_Category_Updated` (`LifecycleState`,`CategoryId`,`UpdatedAt`),
  KEY `IX_Documents_System_State` (`SystemId`,`LifecycleState`),
  KEY `FK_Documents_CurrentVersion` (`CurrentVersionId`),
  CONSTRAINT `FK_Documents_Category` FOREIGN KEY (`CategoryId`) REFERENCES `Categories` (`CategoryId`),
  CONSTRAINT `FK_Documents_CurrentVersion` FOREIGN KEY (`CurrentVersionId`) REFERENCES `DocumentVersions` (`VersionId`),
  CONSTRAINT `FK_Documents_Owner` FOREIGN KEY (`OwnerUserId`) REFERENCES `Users` (`UserId`),
  CONSTRAINT `FK_Documents_System` FOREIGN KEY (`SystemId`) REFERENCES `Systems` (`SystemId`),
  CONSTRAINT `CK_Documents_Type` CHECK (`DocumentType` in ('Manual','POP','Politica','Procedimento')),
  CONSTRAINT `CK_Documents_State` CHECK (`LifecycleState` in ('Publicado','Obsoleto','Inativo','Revisao'))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

